import heapq

def fastest_delivery(n, roads, stations, capacity, swap_time, max_swaps, s, t):
    if s == t:
        return (0, 0)

    # Pre-build graph
    adj = [[] for _ in range(n)]
    for u, v, m, e in roads:
        adj[u].append((v, m, e))

    is_station = [False] * n
    for st in stations:
        if 0 <= st < n:
            is_station[st] = True

    cap_plus_1 = capacity + 1
    stride_c = max_swaps + 1
    stride_u = cap_plus_1 * stride_c
    total_states = n * stride_u

    INF = 10**18
    dist = [INF] * total_states

    # Start at s with full capacity and 0 swaps used
    start_state = (s * cap_plus_1 + capacity) * stride_c + 0
    dist[start_state] = 0

    # Priority queue stores (cost, state_id)
    # cost is encoded as (minutes << 8) | swaps
    pq = [(0, start_state)]

    while pq:
        cost, state_id = heapq.heappop(pq)

        if cost > dist[state_id]:
            continue

        rem, k = divmod(state_id, stride_c)
        u, c = divmod(rem, cap_plus_1)

        if u == t:
            return (cost >> 8, cost & 255)

        # 1. Drive along an outgoing road
        for v, m, e in adj[u]:
            if e > 0 and c < e:
                continue
            new_c = min(capacity, c - e)
            next_state = (v * cap_plus_1 + new_c) * stride_c + k
            new_cost = cost + (m << 8)
            if new_cost < dist[next_state]:
                dist[next_state] = new_cost
                heapq.heappush(pq, (new_cost, next_state))

        # 2. Swap battery at current station
        if is_station[u] and k < max_swaps and c < capacity:
            next_state = (u * cap_plus_1 + capacity) * stride_c + (k + 1)
            new_cost = cost + (swap_time << 8) + 1
            if new_cost < dist[next_state]:
                dist[next_state] = new_cost
                heapq.heappush(pq, (new_cost, next_state))

    return None

def best_context(messages, budget, max_gap, bonus):
    if budget < 0 or max_gap < 0:
        raise ValueError("budget and max_gap must be non-negative.")

    n = len(messages)
    pinned_indices = [i for i, m in enumerate(messages) if m[2]]

    ans = None

    # Case: Empty set S = {}
    if not pinned_indices and n <= max_gap:
        ans = 0

    if n == 0:
        return ans

    # Precompute the last pinned index strictly before i
    last_pinned_before = [-1] * n
    last_p = -1
    for i in range(n):
        last_pinned_before[i] = last_p
        if messages[i][2]:
            last_p = i

    # Precompute the first pinned index strictly after i
    first_pinned_after = [n] * n
    first_p = n
    for i in range(n - 1, -1, -1):
        first_pinned_after[i] = first_p
        if messages[i][2]:
            first_p = i

    INF = float("inf")
    # dp[i][b]: max score with message i kept and total length b
    dp = [[-INF] * (budget + 1) for _ in range(n)]

    for i in range(n):
        length_i, val_i, _ = messages[i]
        if length_i > budget:
            continue

        dp_i = dp[i]

        # Option A: message i is the very first kept message
        if i <= max_gap and last_pinned_before[i] == -1:
            dp_i[length_i] = val_i

        # Option B: message i is preceded by message j = i - 1 (adjacent -> earns bonus)
        if i > 0 and (last_pinned_before[i] <= i - 1):
            dp_prev = dp[i - 1]
            gain = val_i + bonus
            for b in range(length_i, budget + 1):
                prev_score = dp_prev[b - length_i]
                if prev_score != -INF:
                    score = prev_score + gain
                    if score > dp_i[b]:
                        dp_i[b] = score

        # Option C: message i is preceded by j < i - 1 (non-adjacent -> no bonus)
        # j must satisfy: i - 1 - max_gap <= j <= i - 2 and j >= last_pinned_before[i]
        min_j = max(0, i - 1 - max_gap, last_pinned_before[i])
        max_j = i - 2
        if min_j <= max_j:
            # Find the max score among all valid j for each previous budget
            best_prev = [-INF] * (budget + 1)
            for j in range(min_j, max_j + 1):
                dp_j = dp[j]
                for b in range(budget + 1):
                    if dp_j[b] > best_prev[b]:
                        best_prev[b] = dp_j[b]

            for b in range(length_i, budget + 1):
                prev_score = best_prev[b - length_i]
                if prev_score != -INF:
                    score = prev_score + val_i
                    if score > dp_i[b]:
                        dp_i[b] = score

        # If message i can be the last kept message, consider its scores for the answer
        if (n - 1 - i) <= max_gap and first_pinned_after[i] == n:
            max_for_i = max(dp_i)
            if max_for_i != -INF:
                if ans is None or max_for_i > ans:
                    ans = max_for_i

    return ans

def min_pruning_cost(parent, demand, cap, cut_cost, critical, root_cap, penalty):
    n = len(parent)

    # Build tree representation
    children = [[] for _ in range(n)]
    for v in range(1, n):
        children[parent[v]].append(v)

    # Iterative post-order traversal (children appear before parents)
    order = []
    stack = [0]
    visited = [False] * n
    while stack:
        u = stack[-1]
        if not visited[u]:
            visited[u] = True
            for c in children[u]:
                stack.append(c)
        else:
            stack.pop()
            order.append(u)

    # Compute total demand and critical status for each subtree
    tot_demand = list(demand)
    has_critical = list(critical)
    for u in order:
        for c in children[u]:
            tot_demand[u] += tot_demand[c]
            if has_critical[c]:
                has_critical[u] = True

    INF = float('inf')
    dp = [[] for _ in range(n)]

    for u in order:
        cap_limit = min(root_cap if u == 0 else cap[u], tot_demand[u])

        # If node u's own demand exceeds its capacity, it cannot be retained
        if demand[u] > cap_limit:
            dp[u] = []
            continue

        # cur_dp stores pairs of (load, min_cost) for node u
        cur_dp = [(demand[u], 0)]
        cur_max_load = demand[u]

        for c in children[u]:
            # Collect options from child c
            child_opts = {}
            # Option 1: Cut line c (only allowed if c's subtree has no critical nodes)
            if not has_critical[c]:
                child_opts[0] = cut_cost[c] + penalty * tot_demand[c]

            # Option 2: Keep line c
            for l, cost in dp[c]:
                if l not in child_opts or cost < child_opts[l]:
                    child_opts[l] = cost

            if not child_opts:
                cur_dp = []
                break

            child_items = list(child_opts.items())
            child_max_load = max(l for l, _ in child_items)

            # Merge child options into cur_dp
            new_max_l = min(cap_limit, cur_max_load + child_max_load)
            new_dp_arr = [INF] * (new_max_l + 1)

            for l1, c1 in cur_dp:
                for l2, c2 in child_items:
                    l = l1 + l2
                    if l <= new_max_l:
                        cost = c1 + c2
                        if cost < new_dp_arr[l]:
                            new_dp_arr[l] = cost

            cur_dp = [(l, cost) for l, cost in enumerate(new_dp_arr) if cost != INF]
            if not cur_dp:
                break
            cur_max_load = cur_dp[-1][0]

        dp[u] = cur_dp

    if not dp[0]:
        return None
    return min(cost for _, cost in dp[0])

def simulate_vending(prices, stock, bank, events, timeout):
    # Validate timestamp ordering before processing or mutating anything
    prev_t = -1
    for ev in events:
        t = ev[0]
        if t < prev_t:
            raise ValueError("Event timestamps must be non-decreasing.")
        prev_t = t

    # Initialize working state (do not mutate inputs)
    stock_state = dict(stock)
    bank_counts = {
        5: bank.get(5, 0),
        10: bank.get(10, 0),
        25: bank.get(25, 0),
        100: bank.get(100, 0),
    }
    escrow = []
    log = []
    last_activity = None

    def check_timeout(current_t):
        nonlocal last_activity
        if escrow and last_activity is not None and current_t >= last_activity + timeout:
            coins = tuple(sorted(escrow, reverse=True))
            log.append(("TIMEOUT", last_activity + timeout, coins))
            escrow.clear()

    for t, kind, arg in events:
        # Check if an automatic return must fire before this event
        check_timeout(t)

        if kind == "coin":
            val = arg
            if val not in (5, 10, 25, 100) or len(escrow) >= 10:
                log.append(("REJECT", t, val))
            else:
                escrow.append(val)
                last_activity = t

        elif kind == "select":
            slot = arg
            last_activity = t
            if slot not in prices:
                log.append(("UNKNOWN", t, slot))
            elif stock_state[slot] == 0:
                log.append(("SOLD_OUT", t, slot))
            else:
                escrow_total = sum(escrow)
                price = prices[slot]
                if escrow_total < price:
                    log.append(("NEED", t, price - escrow_total))
                else:
                    # Move all escrow coins into the bank
                    for coin in escrow:
                        bank_counts[coin] += 1

                    remaining = escrow_total - price
                    change_coins = []
                    for denom in (100, 25, 10, 5):
                        k = min(bank_counts[denom], remaining // denom)
                        bank_counts[denom] -= k
                        remaining -= k * denom
                        change_coins.extend([denom] * k)

                    if remaining == 0:
                        stock_state[slot] -= 1
                        escrow.clear()
                        log.append(("VEND", t, slot, tuple(change_coins)))
                    else:
                        # Rollback change taken and escrow coins moved into bank
                        for coin in change_coins:
                            bank_counts[coin] += 1
                        for coin in escrow:
                            bank_counts[coin] -= 1
                        log.append(("EXACT_ONLY", t, slot))

        elif kind == "cancel":
            last_activity = t
            if escrow:
                coins = tuple(sorted(escrow, reverse=True))
                log.append(("RETURN", t, coins))
                escrow.clear()

    # Handle any pending automatic return after all events have finished
    if escrow and last_activity is not None:
        coins = tuple(sorted(escrow, reverse=True))
        log.append(("TIMEOUT", last_activity + timeout, coins))
        escrow.clear()

    final_bank = (
        bank_counts[5],
        bank_counts[10],
        bank_counts[25],
        bank_counts[100],
    )
    return log, final_bank

