import re

_IDENT_RE = re.compile(r'^[A-Za-z_][A-Za-z0-9_]*$')


def _type_name(v) -> str:
    if v is None:
        return "null"
    if isinstance(v, bool):
        return "bool"
    if isinstance(v, int):
        return "int"
    if isinstance(v, float):
        return "float"
    if isinstance(v, str):
        return "str"
    if isinstance(v, list):
        return "list"
    if isinstance(v, dict):
        return "dict"
    return type(v).__name__


def _format_path(p: str, name: str) -> str:
    if _IDENT_RE.match(name):
        return f"{p}.{name}"
    return f"{p}[{json.dumps(name, ensure_ascii=False)}]"


def _merge_dict(overlay: dict, target: dict, path: str, layer_idx: int, warnings: list[str]) -> None:
    for k, v in overlay.items():
        if not isinstance(k, str):
            raise TypeError(f"layer {layer_idx}: non-string key at {path}")

        # Classify key and extract NAME
        if k.startswith("-"):
            directive = "DELETE"
            name = k[1:]
        elif k.endswith("+"):
            directive = "APPEND"
            name = k[:-1]
        else:
            directive = "SET"
            name = k

        if not name:
            raise ValueError(f"layer {layer_idx}: empty key name at {path}")

        q = _format_path(path, name)

        if directive == "DELETE":
            if v is not None:
                raise ValueError(f"layer {layer_idx}: delete directive needs null at {q}")
            if name in target:
                del target[name]
            else:
                warnings.append(f"layer {layer_idx}: delete of missing key at {q}")

        elif directive == "APPEND":
            if not isinstance(v, list):
                raise ValueError(f"layer {layer_idx}: append directive needs a list at {q}")
            if name not in target:
                target[name] = copy.deepcopy(v)
            elif isinstance(target[name], list):
                target[name].extend(copy.deepcopy(item) for item in v)
            else:
                raise ValueError(f"layer {layer_idx}: cannot append to {_type_name(target[name])} at {q}")

        else:  # SET
            if name in target and _type_name(target[name]) != _type_name(v):
                warnings.append(
                    f"layer {layer_idx}: type change at {q}: {_type_name(target[name])} -> {_type_name(v)}"
                )

            if isinstance(v, dict):
                if name in target and isinstance(target[name], dict):
                    _merge_dict(v, target[name], q, layer_idx, warnings)
                else:
                    new_dict: dict = {}
                    target[name] = new_dict
                    _merge_dict(v, new_dict, q, layer_idx, warnings)
            else:
                target[name] = copy.deepcopy(v)


def merge_layers(layers) -> tuple[dict, list[str]]:
    if not isinstance(layers, list):
        raise TypeError("layers must be a list")

    result: dict = {}
    warnings: list[str] = []

    for l_idx, layer in enumerate(layers):
        if not isinstance(layer, dict):
            raise TypeError(f"layer {l_idx} is not a dict")
        _merge_dict(layer, result, "$", l_idx, warnings)

    return result, warnings

