def leaderboard_ranks(submissions: list[tuple[str, int]]) -> list[int]:
    if not submissions:
        return []

    n = len(submissions)

    # Pass 1: Identify all keys that will ever be inserted
    player_max: dict[str, int] = {}
    keys_to_insert: list[tuple[int, int]] = []

    for i, (player, score) in enumerate(submissions):
        curr_max = player_max.get(player)
        if curr_max is None or score > curr_max:
            player_max[player] = score
            keys_to_insert.append((-score, i))

    # Coordinate compression: sort keys and map each to a 1-based index
    sorted_keys = sorted(keys_to_insert)
    key_to_idx = {k: idx + 1 for idx, k in enumerate(sorted_keys)}
    m = len(sorted_keys)

    # Fenwick Tree (Binary Indexed Tree)
    bit = [0] * (m + 1)

    def bit_add(idx: int, val: int) -> None:
        while idx <= m:
            bit[idx] += val
            idx += idx & (-idx)

    def bit_query(idx: int) -> int:
        s = 0
        while idx > 0:
            s += bit[idx]
            idx -= idx & (-idx)
        return s

    # Pass 2: Process submissions and record ranks
    player_best: dict[str, tuple[int, int]] = {}
    ranks: list[int] = [0] * n

    for i, (player, score) in enumerate(submissions):
        old_key = player_best.get(player)
        if old_key is None or score > -old_key[0]:
            if old_key is not None:
                bit_add(key_to_idx[old_key], -1)
            new_key = (-score, i)
            player_best[player] = new_key
            new_idx = key_to_idx[new_key]
            bit_add(new_idx, 1)
            ranks[i] = bit_query(new_idx)
        else:
            ranks[i] = bit_query(key_to_idx[old_key])

    return ranks
